                          value={id}
                          id={id}
                          size={size.radioSize}
                        />
                        <FieldLabel htmlFor={id} className={size.labelClass}>
                          Radio label
                        </FieldLabel>
                      </Field>
                    ))}
                  </RadioGroup>
                </FieldSet>
